const fs = require('fs');

// --- minimal robust CSV parser (handles quoted fields with commas) ---
function parseCSV(text) {
  const rows = [];
  let field = '', row = [], inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; }
        else inQuotes = false;
      } else field += c;
    } else {
      if (c === '"') inQuotes = true;
      else if (c === ',') { row.push(field); field = ''; }
      else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
      else if (c === '\r') { /* skip */ }
      else field += c;
    }
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows;
}

const raw = fs.readFileSync('data/steam.csv', 'utf8');
const rows = parseCSV(raw);
const header = rows[0];
const idx = Object.fromEntries(header.map((h, i) => [h, i]));
const data = rows.slice(1).filter(r => r.length === header.length).map(r => {
  const pos = +r[idx.positive_ratings] || 0;
  const neg = +r[idx.negative_ratings] || 0;
  const total = pos + neg;
  // owners is a range "10000000-20000000" -> midpoint
  const ow = (r[idx.owners] || '').split('-').map(Number);
  const ownersMid = ow.length === 2 ? (ow[0] + ow[1]) / 2 : (ow[0] || 0);
  return {
    name: r[idx.name],
    price: +r[idx.price] || 0,
    pos, neg, total,
    ratio: total > 0 ? pos / total : null,
    avgPlay: +r[idx.average_playtime] || 0,
    medPlay: +r[idx.median_playtime] || 0,
    ownersMid,
    genres: r[idx.genres] || '',
  };
});

console.log(`Parsed ${data.length} games (of ${rows.length - 1} rows).`);

// ---------- helpers ----------
const pearson = (xs, ys) => {
  const n = xs.length;
  const mx = xs.reduce((a, b) => a + b, 0) / n;
  const my = ys.reduce((a, b) => a + b, 0) / n;
  let sxy = 0, sxx = 0, syy = 0;
  for (let i = 0; i < n; i++) {
    const dx = xs[i] - mx, dy = ys[i] - my;
    sxy += dx * dy; sxx += dx * dx; syy += dy * dy;
  }
  return sxy / Math.sqrt(sxx * syy);
};
// rank transform for Spearman
const ranks = arr => {
  const sorted = arr.map((v, i) => [v, i]).sort((a, b) => a[0] - b[0]);
  const r = new Array(arr.length);
  let i = 0;
  while (i < sorted.length) {
    let j = i;
    while (j + 1 < sorted.length && sorted[j + 1][0] === sorted[i][0]) j++;
    const avgRank = (i + j) / 2 + 1;
    for (let k = i; k <= j; k++) r[sorted[k][1]] = avgRank;
    i = j + 1;
  }
  return r;
};
const spearman = (xs, ys) => pearson(ranks(xs), ranks(ys));

// ---------- Definition columns ----------
// D1 Reach/Popularity      = total review volume (pos+neg)
// D2 Satisfaction/Quality  = positive ratio (needs enough reviews to be meaningful)
// D3 Engagement            = median playtime (minutes)
// D4 Commercial proxy      = owners midpoint * price  (revenue estimate)

// Use a credibility floor for ratio-based satisfaction
const MIN_REVIEWS = 50;
const credible = data.filter(d => d.total >= MIN_REVIEWS && d.ratio !== null);
console.log(`Games with >=${MIN_REVIEWS} reviews (credible satisfaction): ${credible.length}`);

// ---- Correlations among definitions (on credible set, log-scaled where heavy-tailed) ----
const logp = v => Math.log10(v + 1);
const vol   = credible.map(d => logp(d.total));
const sat   = credible.map(d => d.ratio);
const eng   = credible.map(d => logp(d.medPlay));
const rev   = credible.map(d => logp(d.ownersMid * d.price));
const own   = credible.map(d => logp(d.ownersMid));

console.log('\n=== Spearman rank correlations (credible set) ===');
const defs = { Volume: vol, Satisfaction: sat, Engagement: eng, RevenueProxy: rev, Owners: own };
const keys = Object.keys(defs);
process.stdout.write('             ' + keys.map(k => k.slice(0, 7).padStart(8)).join('') + '\n');
for (const a of keys) {
  let line = a.padEnd(13);
  for (const b of keys) line += spearman(defs[a], defs[b]).toFixed(2).padStart(8);
  console.log(line);
}

// ---------- Top-10 lists under each definition ----------
const topN = (arr, keyFn, n = 10) =>
  [...arr].sort((a, b) => keyFn(b) - keyFn(a)).slice(0, n);

const show = (title, list, fmt) => {
  console.log(`\n--- Top 10 by ${title} ---`);
  list.forEach((d, i) =>
    console.log(`${String(i + 1).padStart(2)}. ${d.name.slice(0, 32).padEnd(33)} ${fmt(d)}`));
};

show('REVIEW VOLUME (Reach)', topN(credible, d => d.total),
  d => `reviews=${d.total}  ratio=${(d.ratio * 100).toFixed(1)}%  medPlay=${d.medPlay}`);

show('SATISFACTION (ratio, >=50 reviews)', topN(credible, d => d.ratio),
  d => `ratio=${(d.ratio * 100).toFixed(1)}%  reviews=${d.total}  medPlay=${d.medPlay}`);

show('SATISFACTION among well-reviewed (>=1000 reviews)',
  topN(credible.filter(d => d.total >= 1000), d => d.ratio),
  d => `ratio=${(d.ratio * 100).toFixed(1)}%  reviews=${d.total}`);

show('ENGAGEMENT (median playtime min)', topN(credible.filter(d => d.medPlay > 0), d => d.medPlay),
  d => `medPlay=${d.medPlay}  reviews=${d.total}  ratio=${(d.ratio * 100).toFixed(1)}%`);

show('REVENUE PROXY (ownersMid*price)', topN(credible, d => d.ownersMid * d.price),
  d => `rev~$${(d.ownersMid * d.price / 1e6).toFixed(1)}M  price=$${d.price}  ratio=${(d.ratio * 100).toFixed(1)}%`);

// ---------- Overlap analysis: how much do the top sets agree? ----------
const setOf = (list) => new Set(list.map(d => d.name));
const top100 = {
  vol: setOf(topN(credible, d => d.total, 100)),
  sat: setOf(topN(credible.filter(d => d.total >= 200), d => d.ratio, 100)),
  eng: setOf(topN(credible.filter(d => d.medPlay > 0), d => d.medPlay, 100)),
  rev: setOf(topN(credible, d => d.ownersMid * d.price, 100)),
};
const overlap = (a, b) => [...a].filter(x => b.has(x)).length;
console.log('\n=== Overlap of Top-100 lists (out of 100) ===');
const ok = Object.keys(top100);
process.stdout.write('       ' + ok.map(k => k.padStart(6)).join('') + '\n');
for (const a of ok) {
  let line = a.padEnd(7);
  for (const b of ok) line += String(overlap(top100[a], top100[b])).padStart(6);
  console.log(line);
}

// ---------- Does volume track satisfaction? Bin by volume, show mean ratio ----------
console.log('\n=== Mean satisfaction by review-volume decile (credible set) ===');
const byVol = [...credible].sort((a, b) => a.total - b.total);
const dn = Math.floor(byVol.length / 10);
for (let i = 0; i < 10; i++) {
  const bin = byVol.slice(i * dn, i === 9 ? byVol.length : (i + 1) * dn);
  const mr = bin.reduce((s, d) => s + d.ratio, 0) / bin.length;
  const lo = bin[0].total, hi = bin[bin.length - 1].total;
  console.log(`decile ${i + 1}: reviews ${String(lo).padStart(5)}-${String(hi).padStart(7)}  meanSat=${(mr * 100).toFixed(1)}%`);
}

// free vs paid satisfaction
const free = credible.filter(d => d.price === 0);
const paid = credible.filter(d => d.price > 0);
const mean = a => a.reduce((s, d) => s + d.ratio, 0) / a.length;
console.log(`\nFree games: n=${free.length} meanSat=${(mean(free) * 100).toFixed(1)}%`);
console.log(`Paid games: n=${paid.length} meanSat=${(mean(paid) * 100).toFixed(1)}%`);

